function makeArticle(slug) {
  const meta = RESEARCH_BLOG_BY_SLUG[slug];
  const topic = TOPIC_DETAILS[slug];
  if (!meta || !topic) return null;
  const keywordPhrase = meta.keywords.replaceAll("; ", ", ");
  return {
    slug,
    quickAnswer: topic.short + " is a focused guide. It covers eligibility, documents, timing, risks and nearby options. Rules and processing instructions can change, so confirm the current requirement on the linked official source before you submit, pay, travel or change status.",
    keyTakeaways: [
      "Start with " + topic.focus + " and identify the decision the route requires.",
      "Check " + topic.evidence + " against the facts entered on every form.",
      "Compare " + topic.short + " with " + topic.compare + " before committing time or fees.",
      "Watch " + topic.timing + " and save the date of the official instruction you used.",
      "Follow this next step only after the current official requirements match your facts: " + topic.next,
    ],
    sections: [
      { id: "what-it-means", heading: "What does " + topic.short + " mean for applicants?", body: [topic.focus + " is the decision at the centre of this guide. " + topic.eligibility, "For people comparing " + keywordPhrase + ", the useful starting point is not a promise of approval. It is a clear record of the facts that create eligibility, the documents that prove them and the current government instruction that controls the decision.", topic.short + " involves records that may come from the applicant, employer, school, province, community, host or family member. Identify who owns each item, what date range it must cover and whether it needs a translation or explanation. Request third-party documents early so a letter, transcript or official notice does not become the point that holds up the next filing."], callout: { label: "Start with the facts", text: topic.focus + ". Treat the official source as the current rulebook and this article as a planning map." } },
      { id: "eligibility-check", heading: "Who should check this pathway first?", body: [topic.eligibility, "For " + topic.short + ", record the status, location, occupation or relationship and date that control the rule. A small change in one of those facts may alter the route, so check each answer against the current form and program instructions before selecting a category."], list: { title: "Eligibility questions to answer", items: ["What exact program, stream or document is being requested?", "Which person, employer, school or community creates eligibility?", "What date, status or location controls the rule?", "Which requirement is substantive and which is only documentary?", "What changed since the last application or review?"] } },
      { id: "evidence-to-prepare", heading: "What evidence should you prepare?", body: [topic.evidence, "For " + topic.short + ", make sure the names, dates and descriptions in the forms agree with the supporting records. Explain a change instead of leaving conflicting versions for an officer to interpret."], table: { caption: "Evidence map for a first review", columns: ["Evidence area", "What to compare"], rows: [["Identity and status", "Passport, permit, expiry date and current location"], ["Eligibility facts", "Program, stream, occupation, study or relationship criteria"], ["Supporting records", "Letters, contracts, transcripts, bank records or employer forms"], ["Dates and intent", "Application date, requested period and next legal step"]] } },
      { id: "compare-the-options", heading: "How does this compare with nearby options?", body: [topic.compare, "For " + topic.short + ", compare the eligibility and evidence this guide describes with the nearest alternative. Note which requirement changes and what that means for status, timing, work, travel, family responsibilities or the next application."], list: { title: "Compare before committing", ordered: true, items: ["The route that matches the facts you can prove today.", "The route that leaves a compliant next step if delayed.", "The documents and third parties required before a deadline.", "The status, travel, work or study consequences while waiting.", "The official page that should be checked again before submission."] } },
      { id: "timing-and-current-rules", heading: "What timing and rule changes should you watch?", body: [topic.timing, "For " + topic.short + ", record when you last checked the official instructions and set a reminder to recheck before applying. If the intake, form or decision window changes, use the dated government notice rather than carrying an older screenshot into a new filing."], callout: { label: "Use a dated source", text: "For " + topic.short + ", save the official instruction and the date you checked it. Reopen that source before acting if the form, intake or decision window may have changed." } },
      { id: "common-mistakes", heading: "What mistakes create avoidable risk?", body: [topic.risk, "For " + topic.short + ", compare the concern with the record that could resolve it. Ask the person or institution who can confirm the fact, and explain any gap before choosing a form or paying a fee."], callout: { label: "Consistency beats volume", text: "For " + topic.short + ", make each important claim traceable to a dated record. A concise, consistent timeline is easier to assess than a larger file with unexplained conflicts." } },
      { id: "next-steps", heading: "What should you do next?", body: [topic.next, "For " + topic.short + ", record who owns the next action and the date by which it must be done. Keep the official source with the evidence map so the plan can be rechecked if the rules or facts change.", "Before submission, test the file against " + topic.focus + ". Could the reviewer verify " + topic.eligibility + " from the supporting records without guessing? If not, add a short explanation and the document that closes the gap. Keep the filed package, receipt and dated instructions together so a later extension, appeal or follow-on application can be checked against the same timeline."], list: { title: "A practical next-step checklist", items: ["Record current status, expiry dates and family facts.", "Open the official source linked below and confirm current requirements.", "Match every eligibility claim to at least one document.", "Write down unanswered questions before paying or submitting.", "Recheck after any job, school, family or travel change."] } },
    ],
    glossary: topic.glossary.map(([term, definition]) => ({ term, definition })),
    faqs: topic.faqs.map(([question, answer]) => ({ question, answer })),
    related: topic.related.map(([href, label]) => ({ href, label, note: "Use this page to move from " + topic.short + " to the next part of the plan." })),
    sources: [
      { url: meta.source, label: topic.sourceLabel },
      { url: topic.secondary[0], label: topic.secondary[1] },
      ...(topic.extraSources || []).map(([url, label]) => ({ url, label })),
    ],
  };
}

export function getAdditionalArticle(slug) {
  return makeArticle(slug);
}

export default getAdditionalArticle;
